solution:
The change in internal energy of the system in an isobaric process is given by

$$
\begin{aligned}
\Delta U & = \Delta H - p \Delta V = \Delta H - p m \left(V_{\text{vapor}} - V_{\text{liquid}}\right) \\
& = 5.417 \times 10^{4} - 1.013 \times 10^{5} \times 0.018 \times \left(1.673 - 1.043 \times 10^{-3}\right) \\
& = 5.112 \times 10^{4} \mathrm{~J}
\end{aligned}
$$

After adiabatic compression, the volume of the gas is reduced by $1\%$, i.e., $\frac{V_{f}}{V_{i}}=0.99$. The partial pressures of He gas and $\mathrm{N}_{2}$ gas are given by

$$
p_{1 f}=p_{1 i}\left(\frac{V_{i}}{V_{f}}\right)^{\gamma_{1}}, \quad p_{2 f}=p_{2 i}\left(\frac{V_{i}}{V_{f}}\right)^{\gamma_{2}}
$$

Substituting the data, we calculate

$$
\begin{aligned}
& p_{1 f}=0.625 \mathrm{~atm} \\
& p_{2 f}=1.247 \mathrm{~atm}
\end{aligned}
$$

The pressure of the mixed gas after adiabatic compression is

$$
p_{f}=p_{1 f}+p_{2 f}=1.87 \mathrm{~atm}
$$

The second-order energy correction is given by

$$
\begin{aligned}
E^{(2)} &= \sum_{m^{\prime}} \frac{\left|\left\langle m^{\prime}\right| H^{\prime} \left| m \right\rangle\right|^{2}}{E_{m}^{(0)}-E_{m^{\prime}}^{(0)}} \\
\left\langle m^{\prime}\right| H^{\prime} \left| m \right\rangle &= -\frac{\mu \varepsilon}{2 \pi} \int_{0}^{2 \pi} \mathrm{~d} \theta \, \mathrm{e}^{\mathrm{i}\left(m-m^{\prime}\right) \theta} \cos \theta \\
&= -\frac{\mu \varepsilon}{2} \left[ \delta_{m^{\prime}, m+1} + \delta_{m^{\prime}, m-1} \right] \\
E^{(2)} &= \frac{\mu^{2} \varepsilon^{2}}{4} \cdot \frac{2 I}{\hbar^{2}} \left[ \frac{1}{m^{2}-(m-1)^{2}} + \frac{1}{m^{2}-(m+1)^{2}} \right] \\
&= \frac{\mu^{2} \varepsilon^{2} I}{\hbar^{2}} \cdot \frac{1}{4 m^{2} - 1}
\end{aligned}
$$

It is evident that $\hat{\pi}^{2} \psi(\boldsymbol{r}) = \hat{\pi} \psi(-\boldsymbol{r}) = \psi(\boldsymbol{r})$, and since $\psi(\boldsymbol{r})$ is arbitrary, it follows that $\hat{\pi}^{2} = 1$. This implies that $\hat{\pi}^{-1} = \hat{\pi} = \hat{\pi}^{\dagger}$, indicating that the parity operator is Hermitian, self-inverse, and unitary. From $\hat{\pi}^{2} = 1$, we deduce that the eigenvalues of $\hat{\pi}$ are $\pm 1$. The corresponding eigenstates are:

$$
\begin{array}{lll}
\hat{\pi} \psi_{+}(\boldsymbol{r}) = \psi_{+}(\boldsymbol{r}), & \psi_{+}(-\boldsymbol{r}) = \psi_{+}(\boldsymbol{r}), & \text{even parity state} \\
\hat{\pi} \psi_{-}(\boldsymbol{r}) = -\psi_{-}(\boldsymbol{r}), & \psi_{-}(-\boldsymbol{r}) = -\psi_{-}(\boldsymbol{r}), & \text{odd parity state}
\end{array}
$$

The time required for the point on disc \( B \) that is initially in contact with disc \( A \) to return to contact with disc \( A \) does not require it to be at the same position as shown in the diagram, nor at the exact previous contact point on disc \( A \). The required time is the time it takes for disc \( B \) to rotate once relative to the connecting rod \( OO' \).

The angular velocity of disc \( B \) relative to the connecting rod \( OO' \) is

\[
\begin{aligned}
\omega_{B} - \Omega &= \omega_{B} - \frac{\omega_{A} a + \omega_{B} b}{a+b} = \frac{(\omega_{B} - \omega_{A}) a}{a+b} \\
t_{2} &= \frac{2 \pi}{|\omega_{B} - \Omega|} = \frac{2 \pi(a+b)}{a|\omega_{B} - \omega_{A}|}
\end{aligned}
\]

The reaction energy for the nuclear reaction ${ }_{7}^{14} \mathrm{~N}+{ }_{2}^{4} \mathrm{He} \rightarrow{ }_{8}^{17} \mathrm{O}+{ }_{1}^{1} \mathrm{H}$ is  

$$
\begin{aligned}
Q & = \left[ M\left({ }^{14} \mathrm{~N}\right) + M\left({ }^{4} \mathrm{He}\right) - M\left({ }^{17} \mathrm{O}\right) - M\left({ }^{1} \mathrm{H}\right) \right] c^{2} \\
& = -0.00128 \, \text{u} \times 931.5 \, \text{MeV/u} = -1.193 \, \text{MeV}
\end{aligned}
$$  
The negative sign indicates this is an endothermic reaction.

In a conductor, \(\boldsymbol{j} = \sigma \boldsymbol{E}, \rho = 0\), so the Maxwell's equations are

$$
\begin{aligned}
& \nabla \times \boldsymbol{E} = -\frac{\partial \boldsymbol{B}}{\partial t}, \quad \nabla \times \boldsymbol{H} = \frac{\partial \boldsymbol{D}}{\partial t} + \boldsymbol{j} \\
& \nabla \cdot \boldsymbol{D} = \nabla \cdot \boldsymbol{B} = 0 \\
& \boldsymbol{D} = \varepsilon \boldsymbol{E}, \quad \boldsymbol{B} = \mu \boldsymbol{H}
\end{aligned}
$$

For steady-state electromagnetic waves

$$
\boldsymbol{E}(\boldsymbol{x}, t) = \boldsymbol{E}(\boldsymbol{x}) e^{-i \omega t}, \quad \boldsymbol{B}(\boldsymbol{x}, t) = \boldsymbol{B}(\boldsymbol{x}) e^{-i \omega t}
$$

From Maxwell's equations, we obtain

\begin{gather*}
\left\{
\begin{array}{l}
\nabla \times \boldsymbol{E}(\boldsymbol{x}) = i \omega \mu \boldsymbol{H}(\boldsymbol{x}) \\
\nabla \times \boldsymbol{H}(\boldsymbol{x}) = -i \omega \varepsilon \boldsymbol{E}(\boldsymbol{x}) + \sigma \boldsymbol{E}(\boldsymbol{x}) \\
\nabla \cdot \boldsymbol{E}(\boldsymbol{x}) = \nabla \cdot \boldsymbol{B}(\boldsymbol{x}) = 0
\end{array}
\right.  \tag{1}\\
\begin{aligned}
\nabla \times (\nabla \times \boldsymbol{E}) = \nabla (\nabla \cdot \boldsymbol{E}) - \nabla^2 \boldsymbol{E} = -\nabla^2 \boldsymbol{E} \\
= i \omega \mu \nabla \times \boldsymbol{H} = (\omega^2 \varepsilon \mu + i \omega \mu \sigma) \boldsymbol{E}
\end{aligned}
\end{gather*}

Let

\begin{equation*}
k^{\prime 2} = \omega^2 \mu \varepsilon^{\prime}, \quad \varepsilon^{\prime} = \varepsilon + i \frac{\sigma}{\omega} \tag{2}
\end{equation*}

Then

\begin{equation*}
\nabla^2 \boldsymbol{E}(\boldsymbol{x}) + k^{\prime 2} \boldsymbol{E}(\boldsymbol{x}) = 0 \tag{3}
\end{equation*}

This is the Helmholtz equation, and a plane wave is one of its solutions:

$$
\boldsymbol{E}(\boldsymbol{x}) = \boldsymbol{E}_{0} e^{i \boldsymbol{k}^{\prime} \cdot \boldsymbol{x}}
$$

where \(\boldsymbol{k}^{\prime}\) is the complex wave vector. Let \(\boldsymbol{k}^{\prime} = \boldsymbol{\beta} + i \boldsymbol{\alpha}\), then

$$
\begin{aligned}
& \beta^2 - \alpha^2 = \omega^2 \mu \varepsilon \\
& \boldsymbol{\beta} \cdot \boldsymbol{\alpha} = \frac{1}{2} \omega \mu \sigma
\end{aligned}
$$

For the problem, the incident wave \( E = E_{y0} e^{i(kz - \omega t)} \), and

$$
\boldsymbol{k} = k \boldsymbol{e}_{z}, \quad \boldsymbol{E}_{0} = \boldsymbol{E}_{y0} \boldsymbol{e}_{y}, \quad \boldsymbol{B}_{0} = \boldsymbol{B}_{x0} \boldsymbol{e}_{x}
$$

Assume the transmitted wave in the semi-infinite medium is \(\boldsymbol{E}^{\prime \prime}, \boldsymbol{B}^{\prime \prime}\), then

$$
\begin{aligned}
\boldsymbol{E}^{\prime \prime} = \boldsymbol{E}_{0}^{\prime \prime} e^{i(k^{\prime} \cdot z - \omega t)}, \quad \boldsymbol{B}^{\prime \prime} = \boldsymbol{B}_{0}^{\prime \prime} e^{i(k^{\prime} \cdot z - \omega t)}
\end{aligned}
$$

At the boundary, to ensure boundary conditions apply at every point on the surface, we must have

$$
\boldsymbol{k} \cdot \boldsymbol{x} = \left.\boldsymbol{k}^{\prime} \cdot \boldsymbol{x}\right|_{z=0}
$$

From which we deduce

$$
\begin{aligned}
& \alpha_{x} = \alpha_{y} = \beta_{x} = \beta_{y} = 0 \\
& \boldsymbol{k}^{\prime} = k^{\prime} \boldsymbol{e}_{z} \\
& k^{\prime} = \beta + i \alpha
\end{aligned}
$$

The \(\beta\), \(\alpha\) satisfy the set of equations

$$
\begin{aligned}
& \beta^2 - \alpha^2 = \omega^2 \mu \varepsilon \\
& \beta \alpha = \frac{1}{2} \omega \mu \sigma
\end{aligned}
$$

The solutions are

\begin{align*}
& \beta = \omega \sqrt{\mu \varepsilon} \left[\frac{1}{2} \left( 1 + \sqrt{1 + \frac{\sigma^2}{\varepsilon^2 \omega^2}} \right)\right]^{1/2}  \tag{4}\\
& \alpha = \omega \sqrt{\mu \varepsilon} \left[\frac{1}{2} \left(-1 + \sqrt{1 + \frac{\sigma^2}{\varepsilon^2 \omega^2}} \right)\right]^{1/2} \tag{5}
\end{align*}

Next, use boundary conditions to find the amplitude of the transmitted wave. Let the amplitude of the reflected wave be \(\boldsymbol{E}_{0}^{\prime}, \boldsymbol{H}_{0}^{\prime}\). Due to the transverse nature of plane waves and the continuity of the normal component of \(\boldsymbol{E}\) and the tangential component of \(\boldsymbol{H}\) at the boundary, one deduces that the electric field of the reflected and refracted waves only has a \(y\) component, and the magnetic field only has an \(x\) component, satisfying

\begin{align*}
& E_{y0} + E_{y0}^{\prime} = E_{y0}^{\prime \prime}  \tag{6}\\
& E_{x0} + E_{x0}^{\prime} = E_{x0}^{\prime \prime} \tag{7}
\end{align*}

For the incident and reflected waves, \(H_{x0} = \sqrt{\frac{\varepsilon_{0}}{\mu_{0}}} E_{y0}, H_{x0}^{\prime} = \sqrt{\frac{\varepsilon_{0}}{\mu_{0}}} E_{y0}^{\prime}\). From equation (1), \(H_{x0}^{\prime \prime} = \frac{k^{\prime}}{\omega \mu} E_{y0}^{\prime \prime}\), thus equation (7) becomes

\begin{equation*}
\sqrt{\frac{\varepsilon_{0}}{\mu_{0}}}(E_{y0} - E_{y0}^{\prime}) = \frac{k^{\prime}}{\omega \mu} E_{y0}^{\prime \prime} \tag{8}
\end{equation*}

Solving equations (6) and (8) together gives

\begin{equation*}
E_{y0}^{\prime \prime} = \frac{2 E_{y0}}{1 + \sqrt{\frac{\mu_{0}}{\varepsilon_{0}}} \cdot \frac{k^{\prime}}{\omega \mu}} \tag{9}
\end{equation*}

When \(\sigma\) is large and real, and \(\omega\) is low frequency, we have

$$
\frac{\sigma}{\varepsilon \omega} \gg 1, \quad \sqrt{1 + \frac{\sigma^2}{\varepsilon^2 \omega^2}} \pm 1 \approx \frac{\sigma}{\varepsilon \omega}
$$

Thus

\begin{equation*}
\beta = \alpha \approx \sqrt{\frac{\omega \mu \sigma}{2}} \tag{10}
\end{equation*}

Therefore,

\begin{align*}
& k^{\prime} = \sqrt{\frac{\omega \mu \sigma}{2}}(1+i) \\
& E_{y0}^{\prime \prime} = \frac{2 E_{y0}}{\left(1 + \sqrt{\frac{\mu_{0} \sigma}{2 \varepsilon_{0} \omega \mu}} + i \sqrt{\frac{\mu_{0} \sigma}{2 \varepsilon_{0} \omega \mu}}\right)} \tag{11}
\end{align*}

The electric field in the metal is therefore

\begin{equation*}
E^{\prime \prime} = E_{y0}^{\prime \prime} e^{-\alpha z} e^{i(\beta z - \omega t)} e_{y} \tag{12}
\end{equation*}

The characteristic impedance of the cable \(Z_{\mathrm{c}} = 20 \, \Omega\), and the internal resistance of the generator \(Z_{\mathrm{s}} = 0\).

\section*{Input Reflection Coefficient}
\[ K_{\text{input}} = \frac{Z_{\mathrm{s}} - Z_{\mathrm{c}}}{Z_{\mathrm{s}} + Z_{\mathrm{c}}} = -1 \]

**Solution Method 1:** When \( x < 0 \), the wave function remains in the form as in equation (1). For \( 0 < x < t \), the Schrödinger equation is

\[
-\frac{\hbar^{2}}{2m} \nabla^{2} \psi = 0
\]

If \( \psi \) takes the form: \( \mathrm{e}^{\mathrm{i} k_{y} \cdot y} \cdot \mathrm{e}^{k x} \), then

\[
-k^{\prime 2} + k^{2} = 0, \quad k = \pm k^{\prime}
\]

Thus, the wave function for \( 0 < x < t \) is

\[
\psi_{2}(x, y) = \left(a \mathrm{e}^{k^{\prime} x} + b \mathrm{e}^{-k^{\prime} x}\right) \mathrm{e}^{i k_{y} \cdot y}
\]

Overall, we have

\[
\begin{array}{ll}
x < 0, & \psi_{1}(x) = \mathrm{e}^{\mathrm{i} k_{x} x} + r \mathrm{e}^{-\mathrm{i} k_{x} x} \\
0 < x < t, & \psi_{2}(x) = a \mathrm{e}^{k^{\prime} x} + b \mathrm{e}^{-k^{\prime} x} \\
x > t, & \psi_{3}(x) = c \mathrm{e}^{\mathrm{i} k_{x} x}
\end{array}
\]

Where

\[
k_{x} = \sqrt{\frac{2mE}{\hbar^{2}}} \cos \theta, \quad k^{\prime} = \sqrt{\frac{2mE}{\hbar^{2}}} \sin \theta
\]

Only the \( x \) component is written here. The \( y \) component is simply \( \mathrm{e}^{\mathrm{i} k_{y} \cdot y} \).

\[
k_{y} = \sqrt{\frac{2mE}{\hbar^{2}}} \sin \theta
\]

All boundary conditions are

\[
\begin{gathered}
\left\{
\begin{array}{l}
1+r = a+b \\
\mathrm{i} k_{x}(1-r) = k^{\prime}(a-b) \\
c \mathrm{e}^{\mathrm{i} k_{x} t} = a \mathrm{e}^{k^{\prime} t} + b \mathrm{e}^{-k^{\prime} t}
\end{array}
\right. \\
\mathrm{i} k_{x} \cdot c \mathrm{e}^{\mathrm{i} k_{x} t} = k^{\prime} a \mathrm{e}^{k^{\prime} t} - k^{\prime} b \mathrm{e}^{-k^{\prime} t}
\end{gathered}
\]

Solving, we have

\[
\begin{gathered}
r = \frac{\mathrm{e}^{2 k^{\prime} t} - 1}{1 - \beta^{2} \mathrm{e}^{2 k^{\prime} t}}, \quad \beta = \frac{k^{\prime} - \mathrm{i} k_{x}}{k^{\prime} + \mathrm{i} k_{x}} \\
|R|^{2} = |r|^{2} = \frac{\mathrm{e}^{2 k^{\prime} t} + \mathrm{e}^{-2 k^{\prime} t} - 2}{\mathrm{e}^{2 k^{\prime} t} + \mathrm{e}^{-2 k^{\prime} t} - 2 \cos 4 \theta}
\end{gathered}
\]

**Solution Method 2:** The problem can also be solved by using the method of amplitude superposition, similar to the case of a Fabry-Perot interferometer in optics.

Only considering the \( x \) component, let \( T_{12}, R_{12} \) represent the amplitude transmission and reflection coefficients for the wave from medium 1 to medium 2 respectively. Let \( T_{21}, R_{21} \) represent the amplitude transmission and reflection coefficients for the wave from medium 2 to medium 1 respectively. Given that the incident wave amplitude is 1, the amplitude of the wave emerging from medium 2 is

\[
\begin{aligned}
T & = T_{12} \mathrm{e}^{-\delta} \cdot T_{21} + T_{12} \mathrm{e}^{-\delta} \cdot R_{21} \mathrm{e}^{-2\delta} R_{21} \cdot T_{21} + T_{12} \mathrm{e}^{-\delta} \cdot \left(R_{21} \mathrm{e}^{-2\delta} R_{21}\right)^{2} \cdot T_{21} + \cdots \\
& = T_{12} \mathrm{e}^{-\delta} T_{21} \left[1 + R_{21}^{2} \mathrm{e}^{-2\delta} + \left(R_{21}^{2} \mathrm{e}^{-2\delta}\right)^{2} + \cdots\right] = T_{12} T_{21} \mathrm{e}^{-\delta} \frac{1}{1 - R_{21}^{2} \mathrm{e}^{-2\delta}}
\end{aligned}
\]

Where \( \mathrm{e}^{-\delta} \) is the attenuation coefficient of the wave traveling from one interface to the other in medium 2.

\[
\delta = k^{\prime} t, \quad k^{\prime} = \sqrt{2mE(1 - \cos^{2} \theta)} / \hbar = \sqrt{2mE} \sin \theta / \hbar
\]

Using the result from (1)

\[
R_{12} = \left(k_{1 x} - k_{2 x}\right) / \left(k_{1 x} + k_{2 x}\right), \quad T_{12} = 1 + R_{12} = 2 k_{1} / \left(k_{1 x} + k_{2 x}\right)
\]

However,

\[
\begin{aligned}
& k_{1 x} = \sqrt{2mE} \cos \theta / \hbar \\
& k_{2 x} = \mathrm{i} k^{\prime} = \mathrm{i} \sqrt{2mE} \sin \theta / \hbar
\end{aligned}
\]

So,

\[
\begin{aligned}
& T_{12} = \frac{2 k_{1 x}}{k_{1 x} + k_{2 x}} = \frac{2 \cos \theta}{\cos \theta + \mathrm{i} \sin \theta} = 2 \cos \theta \mathrm{e}^{-\mathrm{i} \theta} \\
& T_{21} = \frac{2 k_{2 x}}{k_{1 x} + k_{2 x}} = \frac{2 \sin \theta}{\cos \theta + \mathrm{i} \sin \theta} = 2 \mathrm{i} \sin \theta \mathrm{e}^{-\mathrm{i} \theta}
\end{aligned}
\]

\[
R_{21} = \frac{k_{2 x} - k_{1 x}}{k_{1 x} + k_{2 x}} = \frac{\mathrm{i} \sin \theta - \cos \theta}{\mathrm{i} \sin \theta + \cos \theta} = \mathrm{e}^{-2 \mathrm{i} \theta}
\]

Thus,

\[
\begin{aligned}
T & = T_{12} T_{21} \mathrm{e}^{-\delta} \frac{1}{1 - R_{21}^{2} \mathrm{e}^{-2\delta}} \\
& = \frac{4 \mathrm{i} \cos \theta \sin \theta \mathrm{e}^{-2 \mathrm{i} \theta} \cdot \mathrm{e}^{-k^{\prime} t}}{1 - \mathrm{e}^{-4 \mathrm{i} \theta} \mathrm{e}^{-2 k^{\prime} t}} \\
& = \frac{2 \mathrm{i} \sin 2 \theta \mathrm{e}^{-2 \mathrm{i} \theta} \mathrm{e}^{-k^{\prime} t}}{1 - \mathrm{e}^{-4 \mathrm{i} \theta} \mathrm{e}^{-2 k^{\prime} t}}
\end{aligned}
\]

Transmittance

\[
\begin{aligned}
|T|^{2} & = \frac{4 \sin^{2} 2 \theta \mathrm{e}^{-2 k^{\prime} t}}{\left(1 - \mathrm{e}^{-2 k^{\prime} t} \cos 4 \theta\right)^{2} + \left(\mathrm{e}^{-2 k^{\prime} t} \sin 4 \theta\right)^{2}} \\
& = \frac{4 \sin^{2} 2 \theta \mathrm{e}^{-2 k^{\prime} t}}{1 + \mathrm{e}^{-4 k^{\prime} t} - 2 \mathrm{e}^{-2 k^{\prime} t} \cos 4 \theta} \\
& = \frac{4 \sin^{2} 2 \theta}{\mathrm{e}^{2 k^{\prime} t} + \mathrm{e}^{-2 k^{\prime} t} - 2 \cos 4 \theta}
\end{aligned}
\]

Reflectance

\[
\begin{aligned}
1 - |T|^{2} & = 1 - \frac{4 \sin^{2} 2 \theta}{\mathrm{e}^{2 k^{\prime} t} + \mathrm{e}^{-2 k^{\prime} t} - 2 \cos 4 \theta} \\
& = \frac{\mathrm{e}^{2 k^{\prime} t} + \mathrm{e}^{-2 k^{\prime} t} - 2}{\mathrm{e}^{2 k^{\prime} t} + \mathrm{e}^{-2 k^{\prime} t} - 2 \cos 4 \theta}
\end{aligned}
\]

Where

\[
k^{\prime} = \sqrt{2mE} \sin \theta / \hbar
\]

Let \( \alpha = 10^{-10} \, \text{cm} \)

\[
\begin{aligned}
& P = \int_{0}^{\alpha} r^{2} \, \mathrm{d}r \, \psi^* \psi \, \mathrm{d}\Omega \\
& = \int_{0}^{\alpha} r^{2} \, \mathrm{d}r \, \frac{1}{10} \left( 4 \left| R_{10} \right|^{2} + 6 \left| R_{21} \right|^{2} \right) \\
& \left| R_{10} \right|^{2} = \frac{4}{a^{3}} \mathrm{e}^{-2r/a}, \quad \left| R_{21} \right|^{2} = \frac{r^{2}}{24 a^{5}} \mathrm{e}^{-r/a}, \quad a = 5.29 \times 10^{-9} \, \text{cm}
\end{aligned}
\]

Since \( \alpha \ll a \), we have

\[
\mathrm{e}^{-2r/a} \approx 1 - \frac{2r}{a}, \quad \mathrm{e}^{-r/a} \approx 1 - \frac{r}{a}
\]

\[
\begin{aligned}
P & \approx \frac{4}{10} \int_{0}^{\alpha} r^{2} \, \mathrm{d}r \, \frac{4}{a^{3}} \left( 1 - \frac{2r}{a} \right) + \frac{6}{10} \int_{0}^{\alpha} r^{2} \, \mathrm{d}r \, \frac{r^{2}}{24 a^{5}} \left( 1 - \frac{r}{a} \right) \\
& = \left[ \frac{4}{3} \left( \frac{\alpha}{a} \right)^{3} - 2 \left( \frac{\alpha}{a} \right)^{4} \right] \frac{4}{10} + \frac{6}{10} \left[ \frac{1}{120} \left( \frac{\alpha}{a} \right)^{5} - \frac{1}{144} \left( \frac{\alpha}{a} \right)^{6} \right] \\
& \approx \frac{8}{15} \left( \frac{\alpha}{a} \right)^{3} \approx 3.6 \times 10^{-6}
\end{aligned}
\]

Thus, the probability that the particles are in the ground state is

\[
\begin{aligned}
& \rho=\left|\left\langle\varphi_{0} \mid \psi_{0}\right\rangle\right|^{2} \\
& \left|\left\langle\varphi_{0} \mid \psi_{0}\right\rangle\right|=\frac{\sqrt{2}}{R} \int_{0}^{R} \sin \frac{\pi r}{R} \sin \frac{\pi r}{2 R} \, \mathrm{d} r \\
& =\sqrt{2}\left[\left.\frac{\sin \left(\pi-\frac{\pi}{2}\right) \frac{r}{R}}{2\left(\pi-\frac{\pi}{2}\right)}\right|_{0}^{R}-\left.\frac{\sin \left(\pi+\frac{\pi}{2}\right) \frac{r}{R}}{2\left(\pi+\frac{\pi}{2}\right)}\right|_{0}^{R}\right]=\frac{4 \sqrt{2}}{3 \pi} \\
& \rho=\frac{32}{9 \pi^{2}}
\end{aligned}
\]

According to Kepler's Third Law, let the period of the elliptical motion be \( T \),

$$
\begin{gathered}
\frac{T^{2}}{(2R)^{3}} = \frac{\left(\frac{2 \pi R}{v_{0}}\right)^{2}}{R^{3}}, \quad T^{2} = 8 \left(\frac{2 \pi R}{v_{0}}\right)^{2} \\
T = 4 \sqrt{2} \frac{\pi R}{v_{0}}
\end{gathered}
$$

The time required for the journey from \( A \) to \( B \) is half a period,

$$
t = \frac{1}{2} T = 2 \sqrt{2} \frac{\pi R}{v_{0}}
$$

First, try to normalize the wave function

\[
\begin{aligned}
1 & = \int \psi^{*}(x) \psi(x) \mathrm{d} x = |c|^{2} \int\left[\theta(x+a) \theta(a-x)\left(1-\frac{|x|}{a}\right)\right]^{2} \mathrm{d} x \\
& = |c|^{2} \int_{-a}^{a}\left(1-\frac{|x|}{a}\right)^{2} \mathrm{d} x = \frac{2 a}{3}|c|^{2}
\end{aligned}
\]

So

\[
|c|^{2}=\frac{3}{2 a}
\]

Then calculate the expectation value of the Hamiltonian \( H=-\frac{\hbar^{2}}{2 m} \frac{d^{2}}{dx^{2}}+g|x| \)

\[
\bar{H}=\int \psi^{*} H \psi \mathrm{d} x = -\frac{\hbar^{2}}{2 m} \int_{-\infty}^{\infty} \psi^{*}(x) \frac{d^{2}}{d x^{2}} \psi(x) \mathrm{d} x + g \int_{-\infty}^{\infty} \psi^{*}(x)|x| \psi(x) \mathrm{d} x
\]

However,

\[
\begin{gathered}
\int_{-\infty}^{\infty} \psi^{*}(x)|x| \psi(x) \mathrm{d} x = |c|^{2}\left[-\int_{-a}^{0} x\left(1+\frac{x}{a}\right)^{2} \mathrm{d} x + \int_{0}^{a} x\left(1-\frac{x}{a}\right)^{2} \mathrm{d} x \right] \\
= \frac{a^{2}|c|^{2}}{6} = \frac{a}{4} \\
\frac{d}{d x} \psi(x) = c \delta(x+a) \theta(a-x)\left(1-\frac{|x|}{a}\right)-c \theta(x+a) \delta(x-a)\left(1-\frac{|x|}{a}\right) \\
+ c \theta(x+a) \theta(x-a)\left(-\frac{|x|}{x} \cdot \frac{1}{a}\right) \\
\int_{-\infty}^{\infty} \psi^{*}(x) \frac{d^{2}}{d x^{2}} \psi(x) \mathrm{d} x = \left.\psi(x) \frac{d}{d x} \psi(x)\right|_{-\infty}^{\infty}-\int_{-\infty}^{\infty}\left(\frac{d \psi}{d x}\right)^{2} \mathrm{d} x
\end{gathered}
\]

\[
\begin{aligned}
& = -\int_{-\infty}^{\infty}\left(\frac{d \psi}{d x}\right)^{2} \mathrm{d} x = -|c|^{2} \int_{-a}^{a}\left(-\frac{|x|}{x a}\right)^{2} \mathrm{d} x \\
& = -\frac{2|c|^{2}}{a} = -\frac{3}{a^{2}}
\end{aligned}
\]

So

\[
\begin{gathered}
\bar{H} = \frac{3 \hbar^{2}}{2 m a^{2}} + \frac{a}{4} g \\
\frac{\delta \bar{H}}{\delta a} = -\frac{3 \hbar^{2}}{m a^{3}} + \frac{g}{4} = 0
\end{gathered}
\]

Thus

\[
\begin{gathered}
a = \left(\frac{12 \hbar^{2}}{g m}\right)^{\frac{1}{3}} \\
\bar{H} = \frac{3 \hbar^{2}}{2 m}\left(\frac{g m}{12 \hbar^{2}}\right)^{\frac{2}{3}} + \frac{g}{4}\left(\frac{12 \hbar^{2}}{g m}\right)^{\frac{1}{3}} = \frac{3}{4}\left(\frac{3 \hbar^{2} g^{2}}{2 m}\right)^{\frac{1}{3}}
\end{gathered}
\]

Apply Bernoulli's equation to two points, one inside and one outside near the small hole:

$$
\begin{aligned}
