$$

Before the metal is stretched, the density of states of the electrons is

\begin{equation*}
D(\varepsilon)=\pi V\left(\frac{2 m}{h^{2}}\right)^{3 / 2} \sqrt{\varepsilon} \tag{3}
\end{equation*}

At a temperature $T \approx 0 \mathrm{~K}$, the Fermi energy of the electrons is

\begin{equation*}
\varepsilon_{\mathrm{F}}=\frac{h^{2}}{2 m}\left(\frac{3 N}{8 V}\right)^{2 / 3} \tag{4}
\end{equation*}

At a temperature $T \approx 0 \mathrm{~K}$, the energy of the electron gas is

\begin{equation*}
U(T=0 \mathrm{~K})=\int_{0}^{\varepsilon_{\mathrm{F}}} D(\varepsilon) \mathrm{d} \varepsilon=\frac{3}{5} N \varepsilon_{\mathrm{F}} \tag{5}
\end{equation*}

After the metal is stretched, the density of states of the electrons becomes

\begin{equation*}
D^{\prime}(\varepsilon)=\pi V^{\prime}\left(\frac{2 m}{h^{2}}\right)^{3 / 2} \sqrt{\varepsilon} \tag{6}
\end{equation*}

where $V^{\prime}=(1+\alpha) V$. At this point, the Fermi energy of the electrons is

\begin{equation*}
\varepsilon_{\mathrm{F}}^{\prime}=\frac{h^{2}}{2 m}\left(\frac{3 N}{8 V^{\prime}}\right)^{2 / 3}=\left(\frac{1}{1+\alpha}\right)^{2 / 3} \varepsilon_{\mathrm{F}}=\left(1-\frac{2}{3} \alpha\right) \varepsilon_{\mathrm{F}} \tag{7}
\end{equation*}

After the metal is stretched, the energy of the electron gas at a temperature $T \approx 0 \mathrm{~K}$ is

\begin{equation*}
U^{\prime}(T \approx 0 \mathrm{~K})=\frac{3}{5} N \varepsilon_{\mathrm{F}}^{\prime} \tag{8}
\end{equation*}

From equations (4), (5), (7), and (8), the relative change in energy of the electron gas at $T \approx 0 \mathrm{~K}$ before and after the metal is stretched is

\begin{equation*}
\left(\frac{U^{\prime}-U}{U}\right)_{T=0 \mathrm{~K}}=\frac{\varepsilon_{\mathrm{F}}^{\prime}-\varepsilon_{\mathrm{F}}}{\varepsilon_{\mathrm{F}}}=\left(\frac{V}{V^{\prime}}\right)^{2 / 3}-1=\left(\frac{1}{1+\alpha}\right)^{2 / 3}-1 \tag{9}
\end{equation*}

Since $\alpha \ll 1$, equation (9) can be reduced to

\begin{equation*}
\left(\frac{U^{\prime}-U}{U}\right)_{T=0 \mathrm{~K}}=-\frac{2}{3} \alpha \tag{10}
\end{equation*}

Let $m$ and $M$ be the masses of the spaceship and the planet, respectively. When the spaceship is in circular motion,

$$
\begin{gathered}
E = \frac{1}{2} m v_{0}^{2} - \frac{G M m}{R}, \quad \frac{m v_{0}^{2}}{R} = \frac{G M m}{R^{2}} \\
E = \frac{1}{2} m v_{0}^{2} - m v_{0}^{2} = -\frac{1}{2} m v_{0}^{2}, \quad \frac{G M m}{R} = m v_{0}^{2}
\end{gathered}
$$

When the spaceship is in elliptical motion,

$$
E^{\prime} = -\frac{G M m}{2a} = -\frac{G M m}{2 \times 2R} = -\frac{1}{4} m v_{0}^{2}
$$

Additionally, $E^{\prime} = \frac{1}{2} m v^{2} - \frac{G M m}{R}$, where $v$ is the speed at point $A$,

$$
E^{\prime} - E = \frac{1}{2} m v^{2} - \frac{G M m}{R} - \left(\frac{1}{2} m v_{0}^{2} - \frac{G M m}{R}\right) = \frac{1}{2} m v^{2} - \frac{1}{2} m v_{0}^{2}
$$

Also, $E^{\prime} - E = -\frac{1}{4} m v_{0}^{2} - \left(-\frac{1}{2} m v_{0}^{2}\right) = \frac{1}{4} m v_{0}^{2}$,

$$
\begin{aligned}
& \frac{1}{2} m v^{2} - \frac{1}{2} m v_{0}^{2} = \frac{1}{4} m v_{0}^{2} \\
& v^{2} = \frac{3}{2} v_{0}^{2}, \quad v = \sqrt{\frac{3}{2}} v_{0}
\end{aligned}
$$

To enter the elliptical orbit at point $A$, a velocity increment of

$$
v - v_{0} = \left(\sqrt{\frac{3}{2}} - 1\right) v_{0}
$$

is required.

